import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Estimates — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Estimates — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/estimates"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Estimates — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/estimates"}]]},"headers":[],"relativePath":"user-guide/estimates.md","filePath":"user-guide/estimates.md","lastUpdated":1788456779000}'),n={name:"user-guide/estimates.md"};function r(i,e,l,c,d,g){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="estimates-—-user-guide" tabindex="-1">Estimates — User Guide <a class="header-anchor" href="#estimates-—-user-guide" aria-label="Permalink to &quot;Estimates — User Guide&quot;">​</a></h1><h2 id="who-can-use-estimates" tabindex="-1">Who can use Estimates <a class="header-anchor" href="#who-can-use-estimates" aria-label="Permalink to &quot;Who can use Estimates&quot;">​</a></h2><p>Your workspace must have <strong>Invoices</strong> installed first, then the <strong>Estimates</strong> module (both free from Marketplace). Marketplace blocks installing Estimates until Invoices is entitled. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>send</code>, <code>accept</code>, <code>convert</code> as needed).</p><p>Without <strong>assign</strong>, you only see estimates assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Estimates</strong> from the sidebar (<strong>Billing</strong>, after Credit Notes). Search by title or number, filter by status or assignee, toggle <strong>My estimates</strong>, and switch KPI cards (Total, Mine, Draft, Sent, Accepted, Accepted value) to quick-filter the table. The table shows the <strong>latest note</strong> and a <strong>Converted</strong> badge once an estimate has produced an invoice.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted estimate from the row menu</li><li><strong>Delete permanently</strong> requires <code>estimates.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-an-estimate" tabindex="-1">Create an estimate <a class="header-anchor" href="#create-an-estimate" aria-label="Permalink to &quot;Create an estimate&quot;">​</a></h2><ol><li>Click <strong>New estimate</strong></li><li>Optionally choose an <strong>Opportunity</strong> first — this auto-fills <strong>Contact</strong>, <strong>Company</strong>, and <strong>Assignee</strong> when those are set on the opportunity</li><li><strong>Linked quotation:</strong> if the opportunity has exactly one quotation it is selected automatically; if there are multiple, pick one manually (or leave none)</li><li>Enter a title, currency (defaults to your workspace currency; full shared currency list), valid-until date, notes, and optional <strong>Terms &amp; conditions</strong> (rich text — headings, lists, bold/italic/underline)</li><li>Adjust contact/company/assignee if needed (when those modules/permissions apply)</li><li>Choose a shared <strong>line discount type</strong> (none, percent, or fixed), then add lines. When <strong>Products</strong> is installed, optionally <strong>select a product</strong> to auto-fill name, details (from the product description), and unit price — you can still edit those fields. Lines also include Qty, Discount value (when type is not none), Tax %, with optional rich-text <strong>Details</strong> under each row — subtotal, discount, tax, and total update automatically. Tax is applied after line discounts.</li><li>Save</li></ol><p>Edit from the row menu or the record page while the estimate is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Send</strong>, content is locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>An estimate starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Send</strong> (<code>draft → sent</code>) — marks the estimate as sent to the customer (does not email the customer by itself)</li><li><strong>Accept</strong> (<code>sent → accepted</code>) or <strong>Reject</strong> / <strong>Expire</strong> via the status action</li></ul><p>Invalid transitions (e.g. accepting directly from Draft) are rejected with a validation error.</p><h2 id="download-pdf" tabindex="-1">Download PDF <a class="header-anchor" href="#download-pdf" aria-label="Permalink to &quot;Download PDF&quot;">​</a></h2><p><strong>Download PDF</strong> is on the estimate record page and the row menu. It generates a branded PDF using your <strong>Settings → Branding</strong> button color, logo (when uploaded), and company profile — plus line items, discount/tax/total breakdown, and the memo notes. Long notes and terms continue across as many pages as needed.</p><h2 id="email-customer" tabindex="-1">Email customer <a class="header-anchor" href="#email-customer" aria-label="Permalink to &quot;Email customer&quot;">​</a></h2><p>After you <strong>Send</strong> the estimate (status is <strong>Sent</strong>, <strong>Accepted</strong>, <strong>Rejected</strong>, or <strong>Expired</strong>), use <strong>Email customer</strong> on the record page (<code>estimates.send</code>). The dialog pre-fills the linked contact or company email when available; you can add CC recipients, edit the subject and message, and choose whether to attach the PDF. Delivery uses your workspace email configuration and appears in <strong>Settings → Email logs</strong>.</p><h2 id="convert-to-invoice" tabindex="-1">Convert to invoice <a class="header-anchor" href="#convert-to-invoice" aria-label="Permalink to &quot;Convert to invoice&quot;">​</a></h2><p>Once an estimate is <strong>Sent</strong> or <strong>Accepted</strong>, use <strong>Convert to invoice</strong> from the record page or row menu:</p><ul><li>Creates a new <strong>draft</strong> invoice with the same title, notes, terms &amp; conditions, currency, <code>line_discount_type</code>, contact/company, quotation link, assignee, and a copy of every line item (name, body, discounts)</li><li>Marks the estimate <strong>Accepted</strong> automatically if it wasn&#39;t already</li><li>The estimate record page then shows a link to the <strong>converted invoice</strong></li><li>An estimate can only be converted <strong>once</strong> — the action is hidden once a converted invoice already exists</li><li>Convert is also blocked if the estimate’s linked quotation already has an invoice (from converting that quote, another estimate, or billing a contract that copied the quotation). Use a new estimate or invoice from scratch if you still need another bill</li></ul><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Overview</strong> — shows the estimate memo from the create/edit <strong>Notes</strong> field (also printed on the PDF)</li><li><strong>Notes</strong> tab — internal activity notes the team adds after the estimate exists (not the same as the memo)</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, conversion, note, and delete/restore events</li></ul><h2 id="related-records" tabindex="-1">Related records <a class="header-anchor" href="#related-records" aria-label="Permalink to &quot;Related records&quot;">​</a></h2><p>Every estimate record page shows its linked <strong>Contact</strong>, <strong>Company</strong>, <strong>Opportunity</strong>, <strong>Quotation</strong>, and — once converted — the resulting <strong>Invoice</strong>, each with a link to jump straight to that record&#39;s detail view.</p>',27)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
